302|void
303|InitProcess(void)
304|{
305|	PGPROC	   *volatile *procgloballist;
306|
307|	/*
308|	 * ProcGlobal should be set up already (if we are a backend, we inherit
309|	 * this by fork() or EXEC_BACKEND mechanism from the postmaster).
310|	 */
311|	if (ProcGlobal == NULL)
312|		elog(PANIC, "proc header uninitialized");
313|
314|	if (MyProc != NULL)
315|		elog(ERROR, "you already exist");
316|
317|	/* Decide which list should supply our PGPROC. */
318|	if (IsAnyAutoVacuumProcess())
319|		procgloballist = &ProcGlobal->autovacFreeProcs;
320|	else if (IsBackgroundWorker)
321|		procgloballist = &ProcGlobal->bgworkerFreeProcs;
322|	else if (am_walsender)
323|		procgloballist = &ProcGlobal->walsenderFreeProcs;
324|	else
325|		procgloballist = &ProcGlobal->freeProcs;
326|
327|	/*
328|	 * Try to get a proc struct from the appropriate free list.  If this
329|	 * fails, we must be out of PGPROC structures (not to mention semaphores).
330|	 *
331|	 * While we are holding the ProcStructLock, also copy the current shared
332|	 * estimate of spins_per_delay to local storage.
333|	 */
334|	SpinLockAcquire(ProcStructLock);
335|
336|	set_spins_per_delay(ProcGlobal->spins_per_delay);
337|
338|	MyProc = *procgloballist;
339|
340|	if (MyProc != NULL)
341|	{
342|		*procgloballist = (PGPROC *) MyProc->links.next;
343|		SpinLockRelease(ProcStructLock);
344|	}
345|	else
346|	{
347|		/*
348|		 * If we reach here, all the PGPROCs are in use.  This is one of the
349|		 * possible places to detect "too many backends", so give the standard
350|		 * error message.  XXX do we need to give a different failure message
351|		 * in the autovacuum case?
352|		 */
353|		SpinLockRelease(ProcStructLock);
354|		if (am_walsender)
355|			ereport(FATAL,
356|					(errcode(ERRCODE_TOO_MANY_CONNECTIONS),
357|					 errmsg("number of requested standby connections exceeds max_wal_senders (currently %d)",
358|							max_wal_senders)));
359|		ereport(FATAL,
360|				(errcode(ERRCODE_TOO_MANY_CONNECTIONS),
361|				 errmsg("sorry, too many clients already")));
362|	}
363|
364|	/*
365|	 * Cross-check that the PGPROC is of the type we expect; if this were not
366|	 * the case, it would get returned to the wrong list.
367|	 */
368|	Assert(MyProc->procgloballist == procgloballist);
369|
370|	/*
371|	 * Now that we have a PGPROC, mark ourselves as an active postmaster
372|	 * child; this is so that the postmaster can detect it if we exit without
373|	 * cleaning up.  (XXX autovac launcher currently doesn't participate in
374|	 * this; it probably should.)
375|	 */
376|	if (IsUnderPostmaster && !IsAutoVacuumLauncherProcess())
377|		MarkPostmasterChildActive();
378|
379|	/*
380|	 * Initialize all fields of MyProc, except for those previously
381|	 * initialized by InitProcGlobal.
382|	 */
383|	SHMQueueElemInit(&(MyProc->links));
384|	MyProc->waitStatus = PROC_WAIT_STATUS_OK;
385|	MyProc->lxid = InvalidLocalTransactionId;
386|	MyProc->fpVXIDLock = false;
387|	MyProc->fpLocalTransactionId = InvalidLocalTransactionId;
388|	MyProc->xid = InvalidTransactionId;
389|	MyProc->xmin = InvalidTransactionId;
390|	MyProc->pid = MyProcPid;
391|	/* backendId, databaseId and roleId will be filled in later */
392|	MyProc->backendId = InvalidBackendId;
393|	MyProc->databaseId = InvalidOid;
394|	MyProc->roleId = InvalidOid;
395|	MyProc->tempNamespaceId = InvalidOid;
396|	MyProc->isBackgroundWorker = IsBackgroundWorker;
397|	MyProc->delayChkpt = false;
398|	MyProc->statusFlags = 0;
399|	/* NB -- autovac launcher intentionally does not set IS_AUTOVACUUM */
400|	if (IsAutoVacuumWorkerProcess())
401|		MyProc->statusFlags |= PROC_IS_AUTOVACUUM;
402|	MyProc->lwWaiting = false;
403|	MyProc->lwWaitMode = 0;
404|	MyProc->waitLock = NULL;
405|	MyProc->waitProcLock = NULL;
406|	pg_atomic_write_u64(&MyProc->waitStart, 0);
407|#ifdef USE_ASSERT_CHECKING
408|	{
409|		int			i;
410|
411|		/* Last process should have released all locks. */
412|		for (i = 0; i < NUM_LOCK_PARTITIONS; i++)
413|			Assert(SHMQueueEmpty(&(MyProc->myProcLocks[i])));
414|	}
415|#endif
416|	MyProc->recoveryConflictPending = false;
417|
418|	/* Initialize fields for sync rep */
419|	MyProc->waitLSN = 0;
420|	MyProc->syncRepState = SYNC_REP_NOT_WAITING;
421|	SHMQueueElemInit(&(MyProc->syncRepLinks));
422|
423|	/* Initialize fields for group XID clearing. */
424|	MyProc->procArrayGroupMember = false;
425|	MyProc->procArrayGroupMemberXid = InvalidTransactionId;
426|	Assert(pg_atomic_read_u32(&MyProc->procArrayGroupNext) == INVALID_PGPROCNO);
427|
428|	/* Check that group locking fields are in a proper initial state. */
429|	Assert(MyProc->lockGroupLeader == NULL);
430|	Assert(dlist_is_empty(&MyProc->lockGroupMembers));
431|
432|	/* Initialize wait event information. */
433|	MyProc->wait_event_info = 0;
434|
435|	/* Initialize fields for group transaction status update. */
436|	MyProc->clogGroupMember = false;
437|	MyProc->clogGroupMemberXid = InvalidTransactionId;
438|	MyProc->clogGroupMemberXidStatus = TRANSACTION_STATUS_IN_PROGRESS;
439|	MyProc->clogGroupMemberPage = -1;
440|	MyProc->clogGroupMemberLsn = InvalidXLogRecPtr;
441|	Assert(pg_atomic_read_u32(&MyProc->clogGroupNext) == INVALID_PGPROCNO);
442|
443|	/*
444|	 * Acquire ownership of the PGPROC's latch, so that we can use WaitLatch
445|	 * on it.  That allows us to repoint the process latch, which so far
446|	 * points to process local one, to the shared one.
447|	 */
448|	OwnLatch(&MyProc->procLatch);
449|	SwitchToSharedLatch();
450|
451|	/* now that we have a proc, report wait events to shared memory */
452|	pgstat_set_wait_event_storage(&MyProc->wait_event_info);
453|
454|	/*
455|	 * We might be reusing a semaphore that belonged to a failed process. So
456|	 * be careful and reinitialize its value here.  (This is not strictly
457|	 * necessary anymore, but seems like a good idea for cleanliness.)
458|	 */
459|	PGSemaphoreReset(MyProc->sem);
460|
461|	/*
462|	 * Arrange to clean up at backend exit.
463|	 */
464|	on_shmem_exit(ProcKill, 0);
465|
466|	/*
467|	 * Now that we have a PGPROC, we could try to acquire locks, so initialize
468|	 * local state needed for LWLocks, and the deadlock checker.
469|	 */
470|	InitLWLockAccess();
471|	InitDeadLockChecking();
472|}

94|void
95|CreateSharedMemoryAndSemaphores(void)
96|{
97|	PGShmemHeader *shim = NULL;
98|
99|	if (!IsUnderPostmaster)
100|	{
101|		PGShmemHeader *seghdr;
102|		Size		size;
103|		int			numSemas;
104|
105|		/* Compute number of semaphores we'll need */
106|		numSemas = ProcGlobalSemas();
107|		numSemas += SpinlockSemas();
108|
109|		/*
110|		 * Size of the Postgres shared-memory block is estimated via
111|		 * moderately-accurate estimates for the big hogs, plus 100K for the
112|		 * stuff that's too small to bother with estimating.
113|		 *
114|		 * We take some care during this phase to ensure that the total size
115|		 * request doesn't overflow size_t.  If this gets through, we don't
116|		 * need to be so careful during the actual allocation phase.
117|		 */
118|		size = 100000;
119|		size = add_size(size, PGSemaphoreShmemSize(numSemas));
120|		size = add_size(size, SpinlockSemaSize());
121|		size = add_size(size, hash_estimate_size(SHMEM_INDEX_SIZE,
122|												 sizeof(ShmemIndexEnt)));
123|		size = add_size(size, dsm_estimate_size());
124|		size = add_size(size, BufferShmemSize());
125|		size = add_size(size, LockShmemSize());
126|		size = add_size(size, PredicateLockShmemSize());
127|		size = add_size(size, ProcGlobalShmemSize());
128|		size = add_size(size, XLOGShmemSize());
129|		size = add_size(size, CLOGShmemSize());
130|		size = add_size(size, CommitTsShmemSize());
131|		size = add_size(size, SUBTRANSShmemSize());
132|		size = add_size(size, TwoPhaseShmemSize());
133|		size = add_size(size, BackgroundWorkerShmemSize());
134|		size = add_size(size, MultiXactShmemSize());
135|		size = add_size(size, LWLockShmemSize());
136|		size = add_size(size, ProcArrayShmemSize());
137|		size = add_size(size, BackendStatusShmemSize());
138|		size = add_size(size, SInvalShmemSize());
139|		size = add_size(size, PMSignalShmemSize());
140|		size = add_size(size, ProcSignalShmemSize());
141|		size = add_size(size, CheckpointerShmemSize());
142|		size = add_size(size, AutoVacuumShmemSize());
143|		size = add_size(size, ReplicationSlotsShmemSize());
144|		size = add_size(size, ReplicationOriginShmemSize());
145|		size = add_size(size, WalSndShmemSize());
146|		size = add_size(size, WalRcvShmemSize());
147|		size = add_size(size, PgArchShmemSize());
148|		size = add_size(size, ApplyLauncherShmemSize());
149|		size = add_size(size, SnapMgrShmemSize());
150|		size = add_size(size, BTreeShmemSize());
151|		size = add_size(size, SyncScanShmemSize());
152|		size = add_size(size, AsyncShmemSize());
153|#ifdef EXEC_BACKEND
154|		size = add_size(size, ShmemBackendArraySize());
155|#endif
156|
157|		/* freeze the addin request size and include it */
158|		addin_request_allowed = false;
159|		size = add_size(size, total_addin_request);
160|
161|		/* might as well round it off to a multiple of a typical page size */
162|		size = add_size(size, 8192 - (size % 8192));
163|
164|		elog(DEBUG3, "invoking IpcMemoryCreate(size=%zu)", size);
165|
166|		/*
167|		 * Create the shmem segment
168|		 */
169|		seghdr = PGSharedMemoryCreate(size, &shim);
170|
171|		InitShmemAccess(seghdr);
172|
173|		/*
174|		 * Create semaphores
175|		 */
176|		PGReserveSemaphores(numSemas);
177|
178|		/*
179|		 * If spinlocks are disabled, initialize emulation layer (which
180|		 * depends on semaphores, so the order is important here).
181|		 */
182|#ifndef HAVE_SPINLOCKS
183|		SpinlockSemaInit();
184|#endif
185|	}
186|	else
187|	{
188|		/*
189|		 * We are reattaching to an existing shared memory segment. This
190|		 * should only be reached in the EXEC_BACKEND case.
191|		 */
192|#ifndef EXEC_BACKEND
193|		elog(PANIC, "should be attached to shared memory already");
194|#endif
195|	}
196|
197|	/*
198|	 * Set up shared memory allocation mechanism
199|	 */
200|	if (!IsUnderPostmaster)
201|		InitShmemAllocation();
202|
203|	/*
204|	 * Now initialize LWLocks, which do shared memory allocation and are
205|	 * needed for InitShmemIndex.
206|	 */
207|	CreateLWLocks();
208|
209|	/*
210|	 * Set up shmem.c index hashtable
211|	 */
212|	InitShmemIndex();
213|
214|	dsm_shmem_init();
215|
216|	/*
217|	 * Set up xlog, clog, and buffers
218|	 */
219|	XLOGShmemInit();
220|	CLOGShmemInit();
221|	CommitTsShmemInit();
222|	SUBTRANSShmemInit();
223|	MultiXactShmemInit();
224|	InitBufferPool();
225|
226|	/*
227|	 * Set up lock manager
228|	 */
229|	InitLocks();
230|
231|	/*
232|	 * Set up predicate lock manager
233|	 */
234|	InitPredicateLocks();
235|
236|	/*
237|	 * Set up process table
238|	 */
239|	if (!IsUnderPostmaster)
240|		InitProcGlobal();
241|	CreateSharedProcArray();
242|	CreateSharedBackendStatus();
243|	TwoPhaseShmemInit();
244|	BackgroundWorkerShmemInit();
245|
246|	/*
247|	 * Set up shared-inval messaging
248|	 */
249|	CreateSharedInvalidationState();
250|
251|	/*
252|	 * Set up interprocess signaling mechanisms
253|	 */
254|	PMSignalShmemInit();
255|	ProcSignalShmemInit();
256|	CheckpointerShmemInit();
257|	AutoVacuumShmemInit();
258|	ReplicationSlotsShmemInit();
259|	ReplicationOriginShmemInit();
260|	WalSndShmemInit();
261|	WalRcvShmemInit();
262|	PgArchShmemInit();
263|	ApplyLauncherShmemInit();
264|
265|	/*
266|	 * Set up other modules that need some shared memory space
267|	 */
268|	SnapMgrInit();
269|	BTreeShmemInit();
270|	SyncScanShmemInit();
271|	AsyncShmemInit();
272|
273|#ifdef EXEC_BACKEND
274|
275|	/*
276|	 * Alloc the win32 shared backend array
277|	 */
278|	if (!IsUnderPostmaster)
279|		ShmemBackendArrayAllocation();
280|#endif
281|
282|	/* Initialize dynamic shared memory facilities. */
283|	if (!IsUnderPostmaster)
284|		dsm_postmaster_startup(shim);
285|
286|	/*
287|	 * Now give loadable modules a chance to set up their shmem allocations
288|	 */
289|	if (shmem_startup_hook)
290|		shmem_startup_hook();
291|}

