79|/*
80| * CreateSharedMemoryAndSemaphores
81| *		Creates and initializes shared memory and semaphores.
82| *
83| * This is called by the postmaster or by a standalone backend.
84| * It is also called by a backend forked from the postmaster in the
85| * EXEC_BACKEND case.  In the latter case, the shared memory segment
86| * already exists and has been physically attached to, but we have to
87| * initialize pointers in local memory that reference the shared structures,
88| * because we didn't inherit the correct pointer values from the postmaster
89| * as we do in the fork() scenario.  The easiest way to do that is to run
90| * through the same code as before.  (Note that the called routines mostly
91| * check IsUnderPostmaster, rather than EXEC_BACKEND, to detect this case.
92| * This is a bit code-wasteful and could be cleaned up.)
93| */
94|void
95|CreateSharedMemoryAndSemaphores(void)
96|{
97|	PGShmemHeader *shim = NULL;
98|
99|	if (!IsUnderPostmaster)
100|	{
101|		PGShmemHeader *seghdr;
102|		Size		size;
103|		int			numSemas;
104|
105|		/* Compute number of semaphores we'll need */
106|		numSemas = ProcGlobalSemas();
107|		numSemas += SpinlockSemas();
108|
109|		/*
110|		 * Size of the Postgres shared-memory block is estimated via
111|		 * moderately-accurate estimates for the big hogs, plus 100K for the
112|		 * stuff that's too small to bother with estimating.
113|		 *
114|		 * We take some care during this phase to ensure that the total size
115|		 * request doesn't overflow size_t.  If this gets through, we don't
116|		 * need to be so careful during the actual allocation phase.
117|		 */
118|		size = 100000;
119|		size = add_size(size, PGSemaphoreShmemSize(numSemas));
120|		size = add_size(size, SpinlockSemaSize());
121|		size = add_size(size, hash_estimate_size(SHMEM_INDEX_SIZE,
122|												 sizeof(ShmemIndexEnt)));
123|		size = add_size(size, dsm_estimate_size());
124|		size = add_size(size, BufferShmemSize());
125|		size = add_size(size, LockShmemSize());
126|		size = add_size(size, PredicateLockShmemSize());
127|		size = add_size(size, ProcGlobalShmemSize());
128|		size = add_size(size, XLOGShmemSize());
129|		size = add_size(size, CLOGShmemSize());
130|		size = add_size(size, CommitTsShmemSize());
131|		size = add_size(size, SUBTRANSShmemSize());
132|		size = add_size(size, TwoPhaseShmemSize());
133|		size = add_size(size, BackgroundWorkerShmemSize());
134|		size = add_size(size, MultiXactShmemSize());
135|		size = add_size(size, LWLockShmemSize());
136|		size = add_size(size, ProcArrayShmemSize());
137|		size = add_size(size, BackendStatusShmemSize());
138|		size = add_size(size, SInvalShmemSize());
139|		size = add_size(size, PMSignalShmemSize());
140|		size = add_size(size, ProcSignalShmemSize());
141|		size = add_size(size, CheckpointerShmemSize());
142|		size = add_size(size, AutoVacuumShmemSize());
143|		size = add_size(size, ReplicationSlotsShmemSize());
144|		size = add_size(size, ReplicationOriginShmemSize());
145|		size = add_size(size, WalSndShmemSize());
146|		size = add_size(size, WalRcvShmemSize());
147|		size = add_size(size, PgArchShmemSize());
148|		size = add_size(size, ApplyLauncherShmemSize());
149|		size = add_size(size, SnapMgrShmemSize());
150|		size = add_size(size, BTreeShmemSize());
151|		size = add_size(size, SyncScanShmemSize());
152|		size = add_size(size, AsyncShmemSize());
153|#ifdef EXEC_BACKEND
154|		size = add_size(size, ShmemBackendArraySize());
155|#endif
156|
157|		/* freeze the addin request size and include it */
158|		addin_request_allowed = false;
159|		size = add_size(size, total_addin_request);
160|
161|		/* might as well round it off to a multiple of a typical page size */
162|		size = add_size(size, 8192 - (size % 8192));
163|
164|		elog(DEBUG3, "invoking IpcMemoryCreate(size=%zu)", size);
165|
166|		/*
167|		 * Create the shmem segment
168|		 */
169|		seghdr = PGSharedMemoryCreate(size, &shim);
170|
171|		InitShmemAccess(seghdr);
172|
173|		/*
174|		 * Create semaphores
175|		 */
176|		PGReserveSemaphores(numSemas);
177|
178|		/*
179|		 * If spinlocks are disabled, initialize emulation layer (which
180|		 * depends on semaphores, so the order is important here).
181|		 */
182|#ifndef HAVE_SPINLOCKS
183|		SpinlockSemaInit();
184|#endif
185|	}
186|	else
187|	{
188|		/*
189|		 * We are reattaching to an existing shared memory segment. This
190|		 * should only be reached in the EXEC_BACKEND case.
191|		 */
192|#ifndef EXEC_BACKEND
193|		elog(PANIC, "should be attached to shared memory already");
194|#endif
195|	}
196|
197|	/*
198|	 * Set up shared memory allocation mechanism
199|	 */
200|	if (!IsUnderPostmaster)
201|		InitShmemAllocation();
202|
203|	/*
204|	 * Now initialize LWLocks, which do shared memory allocation and are
205|	 * needed for InitShmemIndex.
206|	 */
207|	CreateLWLocks();
208|
209|	/*
210|	 * Set up shmem.c index hashtable
211|	 */
212|	InitShmemIndex();
213|
214|	dsm_shmem_init();
215|
216|	/*
217|	 * Set up xlog, clog, and buffers
218|	 */
219|	XLOGShmemInit();
220|	CLOGShmemInit();
221|	CommitTsShmemInit();
222|	SUBTRANSShmemInit();
223|	MultiXactShmemInit();
224|	InitBufferPool();
225|
226|	/*
227|	 * Set up lock manager
228|	 */
229|	InitLocks();
230|
231|	/*
232|	 * Set up predicate lock manager
233|	 */
234|	InitPredicateLocks();
235|
236|	/*
237|	 * Set up process table
238|	 */
239|	if (!IsUnderPostmaster)
240|		InitProcGlobal();
241|	CreateSharedProcArray();
242|	CreateSharedBackendStatus();
243|	TwoPhaseShmemInit();
244|	BackgroundWorkerShmemInit();
245|
246|	/*
247|	 * Set up shared-inval messaging
248|	 */
249|	CreateSharedInvalidationState();
250|
251|	/*
252|	 * Set up interprocess signaling mechanisms
253|	 */
254|	PMSignalShmemInit();
255|	ProcSignalShmemInit();
256|	CheckpointerShmemInit();
257|	AutoVacuumShmemInit();
258|	ReplicationSlotsShmemInit();
259|	ReplicationOriginShmemInit();
260|	WalSndShmemInit();
261|	WalRcvShmemInit();
262|	PgArchShmemInit();
263|	ApplyLauncherShmemInit();
264|
265|	/*
266|	 * Set up other modules that need some shared memory space
267|	 */
268|	SnapMgrInit();
269|	BTreeShmemInit();
270|	SyncScanShmemInit();
271|	AsyncShmemInit();
272|
273|#ifdef EXEC_BACKEND
274|
275|	/*
276|	 * Alloc the win32 shared backend array
277|	 */
278|	if (!IsUnderPostmaster)
279|		ShmemBackendArrayAllocation();
280|#endif
281|
282|	/* Initialize dynamic shared memory facilities. */
283|	if (!IsUnderPostmaster)
284|		dsm_postmaster_startup(shim);
285|
286|	/*
287|	 * Now give loadable modules a chance to set up their shmem allocations
288|	 */
289|	if (shmem_startup_hook)
290|		shmem_startup_hook();
